import ErrorFactory from '../utils/ErrorFactory'
import Logger from '../utils/Logger'
import * as Request from 'request-promise'

const TOKEN_HEADER = 'x-captain-auth'
const APP_TOKEN_HEADER = 'x-captain-app-token'
const NAMESPACE = 'x-namespace'
const CAPTAIN = 'captain'

export default class HttpClient {
    readonly GET = 'GET'
    readonly POST = 'POST'
    readonly POST_DATA = 'POST_DATA'
    readonly PATCH = 'PATCH'
    isDestroyed = false

    constructor(
        private baseUrl: string,
        private appToken: string | undefined,
        private authToken: string,
        private onAuthFailure: () => Promise<any>
    ) {
        //
    }

    createHeaders() {
        const headers: any = {}
        if (this.authToken) {
            headers[TOKEN_HEADER] = this.authToken
        }

        if (this.appToken) {
            headers[APP_TOKEN_HEADER] = this.appToken
        }

        headers[NAMESPACE] = CAPTAIN

        // check user/appData or apiManager.uploadAppData before changing this signature.
        return headers
    }

    setAuthToken(authToken: string) {
        this.authToken = authToken
    }

    destroy() {
        this.isDestroyed = true
    }

    fetch(
        method: 'GET' | 'POST' | 'POST_DATA' | 'PATCH',
        endpoint: string,
        variables: any
    ) {
        const self = this
        return function (): Promise<any> {
            return Promise.resolve() //
                .then(function () {
                    if (!process.env.REACT_APP_IS_DEBUG) {
                        return Promise.resolve()
                    }
                    return new Promise<void>(function (res) {
                        setTimeout(res, 500)
                    })
                })
                .then(function () {
                    return self.fetchInternal(method, endpoint, variables) //
                })
                .then(function (data) {
                    if (
                        data.status === ErrorFactory.STATUS_AUTH_TOKEN_INVALID
                    ) {
                        return self
                            .onAuthFailure() //
                            .then(function () {
                                return self
                                    .fetchInternal(method, endpoint, variables)
                                    .then(function (newRequestResponse) {
                                        return newRequestResponse
                                    })
                            })
                    } else {
                        return data
                    }
                })
                .then(function (data) {
                    if (
                        data.status !== ErrorFactory.OKAY &&
                        data.status !== ErrorFactory.OKAY_BUILD_STARTED
                    ) {
                        throw ErrorFactory.createError(
                            data.status || ErrorFactory.UNKNOWN_ERROR,
                            data.description || ''
                        )
                    }
                    return data
                })
                .then(function (data) {
                    // tslint:disable-next-line: max-line-length
                    // These two blocks are clearly memory leaks! But I don't have time to fix them now... I need to CANCEL the promise, but since I don't
                    // have CANCEL method on the native Promise, I return a promise that will never RETURN if the HttpClient is destroyed.
                    // tslint:disable-next-line: max-line-length
                    // Will fix them later... but it shouldn't be a big deal anyways as it's only a problem when user navigates away from a page before the
                    // network request returns back.
                    return new Promise(function (resolve, reject) {
                        // data.data here is the "data" field inside the API response! {status: 100, description: "Login succeeded", data: {…}}
                        if (!self.isDestroyed) {
                            return resolve(data.data)
                        }
                        Logger.dev('Destroyed then not called')
                    })
                })
                .catch(function (error) {
                    // Logger.log('');
                    // Logger.error(error.message || error);
                    return new Promise(function (resolve, reject) {
                        if (!self.isDestroyed) {
                            return reject(error)
                        }
                        Logger.dev('Destroyed catch not called')
                    })
                })
        }
    }

    fetchInternal(
        method: 'GET' | 'POST' | 'POST_DATA' | 'PATCH',
        endpoint: string,
        variables: any
    ) {
        if (method === this.GET) {
            return this.getReq(endpoint, variables)
        }

        if (method === this.POST || method === this.POST_DATA) {
            return this.postReq(endpoint, variables, method)
        }

        if (method === this.PATCH) {
            return this.patchReq(endpoint, variables)
        }

        throw new Error('Unknown method: ' + method)
    }

    getReq(endpoint: string, variables: any) {
        const self = this

        return Request.get(this.baseUrl + endpoint, {
            headers: self.createHeaders(),
            qs: variables,
            json: true
        }).then(function (data) {
            return data
        })
    }

    postReq(
        endpoint: string,
        variables: any,
        method: 'GET' | 'POST' | 'POST_DATA'
    ) {
        const self = this

        if (method === this.POST_DATA) {
            return Request.post(this.baseUrl + endpoint, {
                headers: self.createHeaders(),
                formData: variables,
                json: true
            }).then(function (data) {
                return data
            })
        }

        return Request.post(this.baseUrl + endpoint, {
            headers: self.createHeaders(),
            body: variables,
            json: true
        }).then(function (data) {
            return data
        })
    }

    patchReq(endpoint: string, variables: any) {
        const self = this

        return Request.patch(this.baseUrl + endpoint, {
            headers: self.createHeaders(),
            body: variables,
            json: true
        }).then(function (data) {
            return data
        })
    }
}

#!/usr/bin/env node

import { isAbsolute, join } from 'path'
import { writeFileSync } from 'fs'
import Constants from '../utils/Constants'
import Utils from '../utils/Utils'
import StdOutUtil from '../utils/StdOutUtil'
import CliHelper from '../utils/CliHelper'
import CliApiManager from '../api/CliApiManager'
import {
    getErrorForDomain,
    getErrorForPassword,
    getErrorForMachineName,
    userCancelOperation
} from '../utils/ValidationsHandler'
import { IMachine } from '../models/storage/StoredObjects'
import Command, {
    IParams,
    IOption,
    ParamType,
    ICommandLineOptions,
    IParam
} from './Command'

const K = Utils.extendCommonKeys({
    path: 'path',
    method: 'method',
    data: 'data',
    out: 'output'
})

export default class Api extends Command {
    protected command = 'api'

    protected usage =
        '[options]\n' +
        '       api -c file\n' +
        '       api [-c file] [-n name] [-t path] [-m method] [-d dataJsonString]\n' +
        '       api [-c file] -u url [-p password] [-n name] [-t path] [-m method] [-d dataJsonString]\n' +
        '  Use --caproverName to use an already logged in CapRover machine\n' +
        '  Use --caproverUrl and --caproverPassword to login on the fly to a CapRover machine, if also --caproverName is present, login credetials are stored locally'

    protected description =
        'Call a generic API on a specific CapRover machine. Use carefully only if you really know what you are doing!'

    private machines = CliHelper.get().getMachinesAsOptions()

    private machine: IMachine

    protected options = (params?: IParams): IOption[] => [
        this.getDefaultConfigFileOption(),
        {
            name: K.url,
            char: 'u',
            env: 'CAPROVER_URL',
            type: 'input',
            message: `CapRover machine URL address, it is "[http[s]://][${Constants.ADMIN_DOMAIN}.]your-captain-root.domain"`,
            when: false,
            filter: (url: string) => Utils.cleanAdminDomainUrl(url) || url, // If not cleaned url, leave url to fail validation with correct error
            validate: (url: string) => getErrorForDomain(url, true)
        },
        {
            name: K.pwd,
            char: 'p',
            env: 'CAPROVER_PASSWORD',
            type: 'password',
            message: 'CapRover machine password',
            when: !!this.findParamValue(params, K.url),
            validate: (password: string) => getErrorForPassword(password)
        },
        {
            name: K.name,
            char: 'n',
            env: 'CAPROVER_NAME',
            message: params
                ? 'select the CapRover machine name you want to call API to'
                : 'CapRover machine name, to load/store credentials',
            type: 'list',
            choices: this.machines,
            when: !this.findParamValue(params, K.url),
            filter: (name: string) =>
                !this.findParamValue(params, K.name)
                    ? userCancelOperation(!name, true) || name
                    : name.trim(),
            validate: !this.findParamValue(params, K.url)
                ? (name: string) => getErrorForMachineName(name, true)
                : undefined
        },
        CliHelper.get().getEnsureAuthenticationOption(
            '',
            () => this.paramValue(params, K.url),
            () => this.paramValue(params, K.pwd),
            () => this.paramValue(params, K.name),
            async (machine: IMachine) => {
                this.machine = machine
                try {
                    await CliApiManager.get(machine).getCaptainInfo()
                } catch (e) {
                    StdOutUtil.printError(
                        `\nSomething bad happened during calling API to ${StdOutUtil.getColoredMachineUrl(
                            machine.baseUrl
                        )}.\n${e.message || e}`,
                        true
                    )
                }
            }
        ),
        {
            name: K.path,
            char: 't',
            env: 'CAPROVER_API_PATH',
            message:
                'API path to call, starting with / (eg. "/user/system/info")',
            type: 'input',
            default: params && '/user/system/info',
            filter: (path: string) => path.trim(),
            validate: (path: string) =>
                path && path.startsWith('/')
                    ? true
                    : 'Please enter a valid path.'
        },
        {
            name: K.method,
            char: 'm',
            env: 'CAPROVER_API_METHOD',
            message: params
                ? 'select the API method you want to call'
                : `API method to call, one of: ${CliHelper.get().getApiMethodsDescription()}`,
            type: 'list',
            default: params && 'GET',
            choices: CliHelper.get().getApiMethodsAsOptions(),
            filter: (method: string) =>
                !this.findParamValue(params, K.method)
                    ? userCancelOperation(!method, true) || method
                    : method.trim(),
            validate: (method: string) =>
                method && Constants.API_METHODS.includes(method)
                    ? true
                    : `Please enter a valid method, one of: ${CliHelper.get().getApiMethodsDescription()}`
        },
        {
            name: K.data,
            char: 'd',
            env: 'CAPROVER_API_DATA',
            message:
                'API data JSON string' +
                (params
                    ? ''
                    : ' (or also JSON object from config file), for "GET" method they are interpreted as querystring values to be appended to the path'),
            type: 'input',
            filter: (data) => {
                if (data && typeof data === 'string') {
                    try {
                        return JSON.parse(data)
                    } catch {
                        // do nothing
                    }
                }
                return data
            },
            validate: (data) => {
                if (data && typeof data === 'string') {
                    try {
                        JSON.parse(data)
                    } catch (e) {
                        return e as string
                    }
                }
                return true
            }
        },
        {
            name: K.out,
            char: 'o',
            env: 'CAPROVER_API_OUTPUT',
            message:
                'where to log API response output: if "true" log to console, if "false" suppress output, otherwise log to specified file (overwrite already existing)',
            type: 'input',
            default: 'true',
            filter: (out: string) => {
                if (!out) {
                    return 'false'
                }
                out = out.trim() || 'false'
                if (out === 'true' || out === 'false' || isAbsolute(out)) {
                    return out
                }
                return join(process.cwd(), out)
            }
        },
        {
            name: 'confirmedToCall',
            type: 'confirm',
            message: 'are you sure you want to proceed?',
            default: true,
            hide: true,
            when: () =>
                this.paramFrom(params, K.name) === ParamType.Question ||
                this.paramFrom(params, K.path) === ParamType.Question ||
                this.paramFrom(params, K.data) === ParamType.Question,
            preProcessParam: (param: IParam) =>
                param && userCancelOperation(!param.value)
        }
    ]

    protected async preAction(
        cmdLineoptions: ICommandLineOptions
    ): Promise<ICommandLineOptions> {
        StdOutUtil.printMessage(
            'Call generic CapRover API [Experimental Feature]...\n'
        )
        return Promise.resolve(cmdLineoptions)
    }

    protected async action(params: IParams): Promise<void> {
        try {
            const resp = await CliApiManager.get(this.machine).callApi(
                this.findParamValue(params, K.path)!.value,
                this.findParamValue(params, K.method)!.value,
                this.paramValue(params, K.data)
            )
            StdOutUtil.printGreenMessage(`API call completed successfully!\n`)

            const out = this.paramValue<string>(params, K.out)!
            const data = JSON.stringify(resp, null, 2)
            if (out === 'true') {
                StdOutUtil.printMessage(data + '\n')
            } else if (out !== 'false') {
                try {
                    writeFileSync(out, data)
                } catch (e) {
                    StdOutUtil.printWarning(
                        `Error writing API response to file: "${out}".\n`
                    )
                }
            }
        } catch (error) {
            StdOutUtil.printError(
                `\nSomething bad happened calling API ${StdOutUtil.getColoredMachineUrl(
                    this.paramValue<string>(params, K.path)!
                )} at ${
                    this.machine.name
                        ? StdOutUtil.getColoredMachineName(this.machine.name)
                        : StdOutUtil.getColoredMachineUrl(this.machine.baseUrl)
                }.`
            )
            StdOutUtil.errorHandler(error)
        }
    }
}

import Constants from '../utils/Constants'
import StorageHelper from '../utils/StorageHelper'
import { IHashMapGeneric } from '../models/IHashMapGeneric'
import { IMachine } from '../models/storage/StoredObjects'
import ApiManager from './ApiManager'

function hashCode(str: string) {
    let hash = 0
    let i
    let chr
    if (str.length === 0) {
        return hash
    }
    for (i = 0; i < str.length; i++) {
        chr = str.charCodeAt(i)
        hash = (hash << 5) - hash + chr
        hash |= 0 // Convert to 32bit integer
    }
    return hash
}

export default class CliApiManager {
    static instances: IHashMapGeneric<ApiManager> = {}

    static get(capMachine: IMachine) {
        const hashKey = 'v' + hashCode(capMachine.baseUrl)
        if (!CliApiManager.instances[hashKey]) {
            CliApiManager.instances[hashKey] = new ApiManager(
                capMachine.baseUrl + Constants.BASE_API_PATH,
                capMachine.appToken,
                function (token) {
                    capMachine.authToken = token
                    if (capMachine.name) {
                        StorageHelper.get().saveMachine(capMachine)
                    }
                    return Promise.resolve()
                }
            )
        }

        CliApiManager.instances[hashKey].setAuthToken(capMachine.authToken)

        return CliApiManager.instances[hashKey]
    }
}

#!/usr/bin/env node

import Constants from '../utils/Constants'
import Utils from '../utils/Utils'
import StdOutUtil from '../utils/StdOutUtil'
import StorageHelper from '../utils/StorageHelper'
import CliHelper from '../utils/CliHelper'
import DeployHelper from '../utils/DeployHelper'
import CliApiManager from '../api/CliApiManager'
import {
    validateIsGitRepository,
    validateDefinitionFile,
    getErrorForDomain,
    getErrorForPassword,
    getErrorForMachineName,
    userCancelOperation,
    getErrorForAppName,
    getErrorForBranchName
} from '../utils/ValidationsHandler'
import { IAppDef } from '../models/AppDef'
import {
    IMachine,
    IDeployedDirectory,
    IDeployParams
} from '../models/storage/StoredObjects'
import Command, {
    IParams,
    IOption,
    ParamType,
    ICommandLineOptions,
    IParam
} from './Command'

const K = Utils.extendCommonKeys({
    default: 'default',
    branch: 'branch',
    tar: 'tarFile',
    appToken: 'appToken',
    img: 'imageName'
})

export default class Deploy extends Command {
    protected command = 'deploy'

    protected usage =
        '[options]\n' +
        '       deploy -d\n' +
        '       deploy -c file\n' +
        '       deploy [-c file] [-n name] [-a app] [-b branch | -t tarFile | -i image]\n' +
        '       deploy [-c file] -u url [-p password] [-n name] [-a app] [-b branch | -t tarFile | -i image]\n' +
        '  Use --caproverName to use an already logged in CapRover machine\n' +
        '  Use --caproverUrl and --caproverPassword to login on the fly to a CapRover machine, if also --caproverName is present, login credetials are stored locally\n' +
        '  Use one among --branch, --tarFile, --imageName'

    protected description =
        "Deploy your app to a specific CapRover machine. You'll be prompted for missing parameters."

    private machines = CliHelper.get().getMachinesAsOptions()

    private apps: IAppDef[] = []

    private machine: IMachine

    protected options = (params?: IParams): IOption[] => [
        {
            name: K.default,
            char: 'd',
            type: 'confirm',
            message:
                'use previously entered values for the current directory, no others options are considered',
            when: false
        },
        this.getDefaultConfigFileOption(() =>
            this.validateDeploySource(params!)
        ),
        {
            name: K.url,
            char: 'u',
            env: 'CAPROVER_URL',
            aliases: [{ name: 'host', char: 'h' }],
            type: 'input',
            message: `CapRover machine URL address, it is "[http[s]://][${Constants.ADMIN_DOMAIN}.]your-captain-root.domain"`,
            when: false,
            filter: (url: string) => Utils.cleanAdminDomainUrl(url) || url, // If not cleaned url, leave url to fail validation with correct error
            validate: (url: string) => getErrorForDomain(url, true)
        },
        {
            name: K.pwd,
            char: 'p',
            env: 'CAPROVER_PASSWORD',
            aliases: [{ name: 'pass' }],
            type: 'password',
            message: 'CapRover machine password',
            when:
                !!this.findParamValue(params, K.url) &&
                !this.findParamValue(params, K.appToken),
            validate: (password: string) => getErrorForPassword(password)
        },
        {
            name: K.name,
            char: 'n',
            env: 'CAPROVER_NAME',
            message: params
                ? 'select the CapRover machine name you want to deploy to'
                : 'CapRover machine name, to load/store credentials',
            type: 'list',
            choices: this.machines,
            when: !this.findParamValue(params, K.url),
            filter: (name: string) =>
                !this.findParamValue(params, K.name)
                    ? userCancelOperation(!name, true) || name
                    : name.trim(),
            validate: !this.findParamValue(params, K.url)
                ? (name: string) => getErrorForMachineName(name, true)
                : undefined
        },
        CliHelper.get().getEnsureAuthenticationOption(
            this.paramValue(params, K.appToken) || '',
            () => this.paramValue(params, K.url),
            () => this.paramValue(params, K.pwd),
            () => this.paramValue(params, K.name),
            async (machine: IMachine) => {
                this.machine = machine
                try {
                    if (machine.appToken) {
                        this.apps = []
                        return
                    }

                    this.apps =
                        (await CliApiManager.get(machine).getAllApps())
                            .appDefinitions || []
                } catch (e) {
                    StdOutUtil.printError(
                        `\nSomething bad happened during deployment to ${StdOutUtil.getColoredMachineUrl(
                            machine.baseUrl
                        )}.\n${e.message || e}`,
                        true
                    )
                }
            }
        ),
        {
            name: K.app,
            char: 'a',
            env: 'CAPROVER_APP',
            aliases: [{ name: 'appName' }],
            message: params
                ? 'select the app name you want to deploy to'
                : 'app name to deploy to',
            type: 'list',
            choices: () => CliHelper.get().getAppsAsOptions(this.apps),
            filter: (app: string) =>
                !this.findParamValue(params, K.app)
                    ? userCancelOperation(!app, true) || app
                    : app.trim(),
            validate: (app: string) =>
                this.findParamValue(params, K.appToken)
                    ? true
                    : getErrorForAppName(this.apps, app)
        },
        {
            name: K.branch,
            char: 'b',
            env: 'CAPROVER_BRANCH',
            message:
                'git branch name to be deployed' +
                (!params
                    ? ', current directory must be git root directory'
                    : ''),
            type: 'input',
            default:
                params && (process.env.CAPROVER_DEFAULT_BRANCH || 'master'),
            when:
                !this.findParamValue(params, K.tar) &&
                !this.findParamValue(params, K.img),
            validate: (branch: string) => getErrorForBranchName(branch)
        },
        {
            name: K.tar,
            char: 't',
            env: 'CAPROVER_TAR_FILE',
            message:
                'tar file to be uploaded, must contain captain-definition file',
            type: 'input',
            when: false
        },
        {
            name: K.img,
            char: 'i',
            env: 'CAPROVER_IMAGE_NAME',
            message:
                'image name to be deployed, it should either exist on server, or it has to be public, or on a private repository that CapRover has access to',
            type: 'input',
            when: false
        },
        {
            name: K.appToken,
            env: 'CAPROVER_APP_TOKEN',
            message: 'app Token',
            type: 'input',
            when: false
        },
        {
            name: 'confirmedToDeploy',
            type: 'confirm',
            message: () =>
                (this.findParamValue(params, K.branch)
                    ? 'note that uncommitted and gitignored files (if any) will not be pushed to server! A'
                    : 'a') + 're you sure you want to deploy?',
            default: true,
            hide: true,
            when: () =>
                this.paramFrom(params, K.name) === ParamType.Question ||
                this.paramFrom(params, K.app) === ParamType.Question ||
                this.paramFrom(params, K.branch) === ParamType.Question,
            preProcessParam: (param: IParam) =>
                param && userCancelOperation(!param.value)
        }
    ]

    protected async preAction(
        cmdLineoptions: ICommandLineOptions
    ): Promise<ICommandLineOptions | undefined> {
        StdOutUtil.printMessage('Preparing deployment to CapRover...\n')

        const possibleApp = StorageHelper.get()
            .getDeployedDirectories()
            .find((dir: IDeployedDirectory) => dir.cwd === process.cwd())
        if (cmdLineoptions[K.default]) {
            if (possibleApp && possibleApp.machineNameToDeploy) {
                if (
                    !StorageHelper.get().findMachine(
                        possibleApp.machineNameToDeploy
                    )
                ) {
                    StdOutUtil.printError(
                        `You have to first login to ${StdOutUtil.getColoredMachineName(
                            possibleApp.machineNameToDeploy
                        )} CapRover machine to use previously saved deploy options from this directory with --default.\n`,
                        true
                    )
                }
                this.options = (params?: IParams) => [
                    CliHelper.get().getEnsureAuthenticationOption(
                        '',
                        undefined,
                        undefined,
                        possibleApp.machineNameToDeploy,
                        async (machine: IMachine) => {
                            this.machine = machine
                            try {
                                this.apps =
                                    (
                                        await CliApiManager.get(
                                            machine
                                        ).getAllApps()
                                    ).appDefinitions || []
                            } catch (e) {
                                StdOutUtil.printError(
                                    `\nSomething bad happened during deployment to ${StdOutUtil.getColoredMachineName(
                                        machine.name
                                    )}.\n${e.message || e}`,
                                    true
                                )
                            }

                            const appErr = getErrorForAppName(
                                this.apps,
                                possibleApp.appName
                            )
                            if (appErr !== true) {
                                StdOutUtil.printError(
                                    `\n${appErr || 'Error!'}\n`,
                                    true
                                )
                            }

                            if (params) {
                                params[K.app] = {
                                    value: possibleApp.appName,
                                    from: ParamType.Default
                                }
                                if (possibleApp.deploySource.branchToPush) {
                                    params[K.branch] = {
                                        value: possibleApp.deploySource
                                            .branchToPush,
                                        from: ParamType.Default
                                    }
                                } else if (
                                    possibleApp.deploySource.tarFilePath
                                ) {
                                    params[K.tar] = {
                                        value: possibleApp.deploySource
                                            .tarFilePath,
                                        from: ParamType.Default
                                    }
                                } else {
                                    params[K.img] = {
                                        value: possibleApp.deploySource
                                            .imageName,
                                        from: ParamType.Default
                                    }
                                }
                                this.validateDeploySource(params)
                            }
                        }
                    )
                ]
                return Promise.resolve({})
            } else {
                StdOutUtil.printError(
                    `Can't find previously saved deploy options from this directory, can't use --default.\n`
                )
                StdOutUtil.printMessage('Falling back to asking questions...\n')
            }
        } else if (
            possibleApp &&
            possibleApp.machineNameToDeploy &&
            StorageHelper.get().findMachine(possibleApp.machineNameToDeploy)
        ) {
            StdOutUtil.printTip('**** Protip ****')
            StdOutUtil.printMessage(
                `You seem to have deployed ${StdOutUtil.getColoredMachineName(
                    possibleApp.appName
                )} from this directory in the past, use --default flag to avoid having to re-enter the information.\n`
            )
        }

        return Promise.resolve(cmdLineoptions)
    }

    protected validateDeploySource(params: IParams) {
        if (
            (this.findParamValue(params, K.branch) ? 1 : 0) +
                (this.findParamValue(params, K.tar) ? 1 : 0) +
                (this.findParamValue(params, K.img) ? 1 : 0) >
            1
        ) {
            StdOutUtil.printError(
                'Only one of branch, tarFile or imageName can be present in deploy.\n',
                true
            )
        }
        if (
            !this.findParamValue(params, K.tar) &&
            !this.findParamValue(params, K.img)
        ) {
            validateIsGitRepository()
            validateDefinitionFile()
        }
    }

    protected async action(params: IParams): Promise<void> {
        await this.deploy(
            {
                captainMachine: this.machine,
                deploySource: {
                    branchToPush: this.paramValue(params, K.branch),
                    tarFilePath: this.paramValue(params, K.tar),
                    imageName: this.paramValue(params, K.img)
                },
                appName: this.paramValue(params, K.app)
            },
            this.apps.find(
                (app) => app.appName === this.paramValue(params, K.app)
            )
        )
    }

    private async deploy(deployParams: IDeployParams, app?: IAppDef) {
        try {
            if (
                await new DeployHelper(
                    app && app.hasDefaultSubDomainSsl
                ).startDeploy(deployParams)
            ) {
                StorageHelper.get().saveDeployedDirectory({
                    appName: deployParams.appName || '',
                    cwd: process.cwd(),
                    deploySource: deployParams.deploySource,
                    machineNameToDeploy: deployParams.captainMachine
                        ? deployParams.captainMachine.name
                        : ''
                })
            }
        } catch (error) {
            const errorMessage = error.message ? error.message : error
            StdOutUtil.printError(
                `\nSomething bad happened: cannot deploy ${StdOutUtil.getColoredAppName(
                    deployParams.appName || ''
                )} at ${StdOutUtil.getColoredMachineName(
                    deployParams.captainMachine
                        ? deployParams.captainMachine.name ||
                              deployParams.captainMachine.baseUrl
                        : ''
                )}.\n${errorMessage}\n`,
                true
            )
        }
    }
}

import * as fs from 'fs-extra'
import * as path from 'path'
import { exec, ExecException } from 'child_process'
import * as ProgressBar from 'progress'
import StdOutUtil from '../utils/StdOutUtil'
import SpinnerHelper from '../utils/SpinnerHelper'
import IBuildLogs from '../models/IBuildLogs'
import { IMachine, IDeployParams } from '../models/storage/StoredObjects'
import CliApiManager from '../api/CliApiManager'

export default class DeployHelper {
    private lastLineNumberPrinted = -10000 // we want to show all lines to begin with!

    constructor(private ssl?: boolean) {}

    async startDeploy(deployParams: IDeployParams): Promise<boolean> {
        const appName = deployParams.appName
        const branchToPush = deployParams.deploySource.branchToPush
        const tarFilePath = deployParams.deploySource.tarFilePath
        const imageName = deployParams.deploySource.imageName
        const machineToDeploy = deployParams.captainMachine

        if (!appName || !machineToDeploy) {
            StdOutUtil.printError(
                "Can't deploy: missing CapRover machine or app name.\n",
                true
            )
            return false
        }

        if (
            (branchToPush ? 1 : 0) +
                (imageName ? 1 : 0) +
                (tarFilePath ? 1 : 0) !==
            1
        ) {
            StdOutUtil.printError(
                "Can't deploy: only one of branch, tarFile or imageName can be present.\n",
                true
            )
            return false
        }

        let gitHash = ''
        let tarFileCreatedByCli = false
        const tarFileNameToDeploy = tarFilePath
            ? tarFilePath
            : 'temporary-captain-to-deploy.tar'
        const tarFileFullPath = tarFileNameToDeploy.startsWith('/')
            ? tarFileNameToDeploy
            : path.join(process.cwd(), tarFileNameToDeploy)

        if (branchToPush) {
            tarFileCreatedByCli = true
            StdOutUtil.printMessage(`Saving tar file to: "${tarFileFullPath}"`)
            gitHash = await this.gitArchiveFile(tarFileFullPath, branchToPush)
        }

        StdOutUtil.printMessage(
            `Deploying ${StdOutUtil.getColoredAppName(appName)} to ${
                machineToDeploy.name
                    ? StdOutUtil.getColoredMachineName(machineToDeploy.name)
                    : StdOutUtil.getColoredMachineUrl(machineToDeploy.baseUrl)
            }...\n`
        )
        try {
            if (imageName) {
                await CliApiManager.get(
                    machineToDeploy
                ).uploadCaptainDefinitionContent(
                    appName,
                    { schemaVersion: 2, imageName },
                    '',
                    true
                )
            } else {
                await CliApiManager.get(machineToDeploy).uploadAppData(
                    appName,
                    this.getFileStream(tarFileFullPath),
                    gitHash
                )
            }

            StdOutUtil.printMessage('Building your source code...\n')

            if (machineToDeploy.appToken) {
                StdOutUtil.printMessage(
                    `Deploying ${StdOutUtil.getColoredAppName(
                        appName
                    )} using app token is in progress. Build logs aren't retrieved when using app token.\nWait a few minutes until your app is built and deployed`
                )
            } else {
                this.startFetchingBuildLogs(machineToDeploy, appName)
            }
            return true
        } catch (e) {
            throw e
        } finally {
            if (tarFileCreatedByCli && fs.pathExistsSync(tarFileFullPath)) {
                fs.removeSync(tarFileFullPath)
            }
        }
    }

    private gitArchiveFile(zipFileFullPath: string, branchToPush: string) {
        return new Promise<string>(function (resolve, reject) {
            if (fs.pathExistsSync(zipFileFullPath)) {
                fs.removeSync(zipFileFullPath)
            } // Removes the temporary file created

            exec(
                `git archive --format tar --output "${zipFileFullPath}" ${branchToPush}`,
                (
                    error: ExecException | null,
                    stdout1: string,
                    stderr1: string
                ) => {
                    if (error) {
                        StdOutUtil.printError(`TAR file failed.\n${error}\n`)
                        if (fs.pathExistsSync(zipFileFullPath)) {
                            fs.removeSync(zipFileFullPath)
                        }
                        reject(new Error('TAR file failed'))
                        return
                    }

                    exec(
                        `git rev-parse ${branchToPush}`,
                        (
                            err: ExecException | null,
                            stdout2: string,
                            stderr2: string
                        ) => {
                            const gitHash = (stdout2 || '').trim()

                            if (err || !/^[a-f0-9]{40}$/.test(gitHash)) {
                                StdOutUtil.printError(
                                    `Cannot find hash of last commit on branch "${branchToPush}": ${gitHash}\n${err}\n`
                                )
                                if (fs.pathExistsSync(zipFileFullPath)) {
                                    fs.removeSync(zipFileFullPath)
                                }
                                reject(new Error('rev-parse failed'))
                                return
                            }

                            StdOutUtil.printMessage(
                                `Using last commit on "${branchToPush}": ${gitHash}\n`
                            )
                            resolve(gitHash)
                        }
                    )
                }
            )
        })
    }

    private getFileStream(zipFileFullPath: string) {
        const fileSize = fs.statSync(zipFileFullPath).size
        const fileStream = fs.createReadStream(zipFileFullPath)
        const barOpts = { width: 20, total: fileSize, clear: false }
        const bar = new ProgressBar(
            'Uploading [:bar] :percent  (ETA :etas)',
            barOpts
        )

        fileStream.on('data', (chunk) => bar.tick(chunk.length))
        fileStream.on('end', () => {
            StdOutUtil.printGreenMessage(`Upload done.\n`)
            StdOutUtil.printMessage(
                'This might take several minutes. PLEASE BE PATIENT...\n'
            )
        })

        return fileStream
    }

    private async onLogRetrieved(
        data: IBuildLogs | undefined,
        machineToDeploy: IMachine,
        appName: string
    ) {
        if (data) {
            const lines = data.logs.lines
            const firstLineNumberOfLogs = data.logs.firstLineNumber
            let firstLinesToPrint = 0
            if (firstLineNumberOfLogs > this.lastLineNumberPrinted) {
                if (firstLineNumberOfLogs < 0) {
                    // This is the very first fetch, probably firstLineNumberOfLogs is around -50
                    firstLinesToPrint = -firstLineNumberOfLogs
                } else {
                    StdOutUtil.printMessage('[[ TRUNCATED ]]')
                }
            } else {
                firstLinesToPrint =
                    this.lastLineNumberPrinted - firstLineNumberOfLogs
            }
            this.lastLineNumberPrinted = firstLineNumberOfLogs + lines.length
            for (let i = firstLinesToPrint; i < lines.length; i++) {
                StdOutUtil.printMessage((lines[i] || '').trim())
            }
        }

        if (data && !data.isAppBuilding) {
            if (!data.isBuildFailed) {
                let appUrl = machineToDeploy.baseUrl
                    .replace('https://', 'http://')
                    .replace('//captain.', `//${appName}.`)
                if (this.ssl) {
                    appUrl = appUrl.replace('http://', 'https://')
                }
                StdOutUtil.printGreenMessage(
                    `\nDeployed successfully ${StdOutUtil.getColoredAppName(
                        appName
                    )}`
                )
                StdOutUtil.printGreenMessage(
                    `App is available at ${StdOutUtil.getColoredMachineUrl(
                        appUrl
                    )}\n`,
                    true
                )
            } else {
                StdOutUtil.printError(
                    `\nSomething bad happened. Cannot deploy ${StdOutUtil.getColoredAppName(
                        appName
                    )} at ${StdOutUtil.getColoredMachineName(
                        machineToDeploy.name || machineToDeploy.baseUrl
                    )}.\n`,
                    true
                )
            }
        } else {
            setTimeout(
                () => this.startFetchingBuildLogs(machineToDeploy, appName),
                2000
            )
        }
    }

    private async startFetchingBuildLogs(
        machineToDeploy: IMachine,
        appName: string
    ) {
        try {
            const data =
                await CliApiManager.get(machineToDeploy).fetchBuildLogs(appName)
            this.onLogRetrieved(data, machineToDeploy, appName)
        } catch (error) {
            StdOutUtil.printError(
                `\nSomething bad happened while retrieving ${StdOutUtil.getColoredAppName(
                    appName
                )} app build logs.\n${error.message || error}\n`
            )
            this.onLogRetrieved(undefined, machineToDeploy, appName)
        }
    }
}

import { IMachine, IDeployedDirectory } from '../models/storage/StoredObjects'
import ConfigStore = require('configstore')
import Utils from './Utils'

const CAP_MACHINES = 'CapMachines'
const DEPLOYED_DIRS = 'DeployedDirs'

export default class StorageHelper {
    static instance: StorageHelper

    static get() {
        if (!StorageHelper.instance) {
            StorageHelper.instance = new StorageHelper()
        }
        return StorageHelper.instance
    }

    private data: ConfigStore

    constructor() {
        this.data = new ConfigStore('caprover')
    }

    getMachines(): IMachine[] {
        return Utils.copyObject(this.data.get(CAP_MACHINES) || [])
    }

    findMachine(machineName: string) {
        return this.getMachines().find((m) => m.name === machineName)
    }

    removeMachine(machineName: string) {
        const machines = this.getMachines()
        const removedMachine = machines.filter(
            (machine) => machine.name === machineName
        )[0]
        const newMachines = machines.filter(
            (machine) => machine.name !== machineName
        )
        this.data.set(CAP_MACHINES, newMachines)

        return removedMachine
    }

    saveMachine(machineToSaveOrUpdate: IMachine) {
        const currMachines = this.getMachines()
        let updatedMachine = false
        for (let index = 0; index < currMachines.length; index++) {
            const element = currMachines[index]
            if (element.name === machineToSaveOrUpdate.name) {
                updatedMachine = true
                currMachines[index] = machineToSaveOrUpdate
                break
            }
        }

        if (!updatedMachine) {
            currMachines.push(machineToSaveOrUpdate)
        }

        this.data.set(CAP_MACHINES, currMachines)
    }

    getDeployedDirectories(): IDeployedDirectory[] {
        return Utils.copyObject(this.data.get(DEPLOYED_DIRS) || [])
    }

    saveDeployedDirectory(directoryToSaveOrUpdate: IDeployedDirectory) {
        if (
            !directoryToSaveOrUpdate ||
            !directoryToSaveOrUpdate.appName ||
            !directoryToSaveOrUpdate.cwd ||
            !directoryToSaveOrUpdate.machineNameToDeploy
        ) {
            return
        }

        const currDirs = this.getDeployedDirectories()
        let updatedDir = false
        for (let index = 0; index < currDirs.length; index++) {
            const element = currDirs[index]
            if (element.cwd === directoryToSaveOrUpdate.cwd) {
                updatedDir = true
                currDirs[index] = directoryToSaveOrUpdate
                break
            }
        }

        if (!updatedDir) {
            currDirs.push(directoryToSaveOrUpdate)
        }

        this.data.set(DEPLOYED_DIRS, currDirs)
    }
}

import * as fs from 'fs-extra'
import { execSync } from 'child_process'
import { sync as commandExistsSync } from 'command-exists'
import StdOutUtil from './StdOutUtil'
import StorageHelper from './StorageHelper'
import Constants from './Constants'
import Utils from './Utils'
import { IAppDef } from '../models/AppDef'
const isWindows = process.platform === 'win32'

export function validateIsGitRepository() {
    if (!fs.pathExistsSync('./.git')) {
        StdOutUtil.printError(
            'You are not in a git root directory: this command will only deploy the current directory.\n' +
                'Run "caprover deploy --help" to know more deployment options... (e.g. tar file or image name)\n',
            true
        )
    }
    if (!commandExistsSync('git')) {
        StdOutUtil.printError(
            '"git" command not found: CapRover needs "git" to create tar file from your branch source files.\n' +
                'Run "caprover deploy --help" to know more deployment options... (e.g. tar file or image name)\n',
            true
        )
    }
}

export function validateDefinitionFile() {
    if (!fs.pathExistsSync('./captain-definition')) {
        if (fs.pathExistsSync('./Dockerfile')) {
            StdOutUtil.printWarning('**** Warning ****')
            StdOutUtil.printMessage(
                'No captain-definition was found in main directory: falling back to Dockerfile.\n'
            )
        } else {
            StdOutUtil.printWarning('**** Warning ****')
            StdOutUtil.printMessage(
                'No captain-definition was found in main directory: unless you have specified a special path for your captain-definition, this build will fail!\n'
            )
        }
    } else {
        let content = null
        try {
            content = JSON.parse(
                fs.readFileSync('./captain-definition', 'utf8')
            )
        } catch (e) {
            StdOutUtil.printError(
                `captain-definition file is not a valid JSON!\n${
                    e.message || e
                }\n`,
                true
            )
        }
        if (!content || !content.schemaVersion) {
            StdOutUtil.printError(
                'captain-definition needs "schemaVersion": please see docs!\n',
                true
            )
        }
    }
}

export function isNameValid(value: string): boolean {
    return !!(value && value.match(/^[-\d\w]+$/i) && !value.includes('--'))
}

export function getErrorForIP(value: string): true | string {
    value = value.trim()
    if (value === Constants.SAMPLE_IP) {
        return 'Enter a valid IP.'
    }
    if (!Utils.isIpAddress(value)) {
        return `This is an invalid IP: ${value}.`
    }
    return true
}

export function getErrorForDomain(
    value: string,
    skipAlreadyStored?: boolean
): true | string {
    if (value === Constants.SAMPLE_DOMAIN) {
        return 'Enter a valid URL.'
    }
    const cleaned = Utils.cleanAdminDomainUrl(value)
    if (!cleaned) {
        return `This is an invalid URL: ${StdOutUtil.getColoredMachineUrl(
            value
        )}.`
    }
    if (!skipAlreadyStored) {
        const found = StorageHelper.get()
            .getMachines()
            .find(
                (machine) =>
                    Utils.cleanAdminDomainUrl(machine.baseUrl) === cleaned
            )
        if (found) {
            return `${StdOutUtil.getColoredMachineUrl(
                cleaned
            )} already exist as ${StdOutUtil.getColoredMachineName(
                found.name
            )} in your currently logged in machines. If you want to replace the existing entry, you have to first use <logout> command, and then re-login.`
        }
    }
    return true
}

export function getErrorForPassword(
    value: string,
    constraint?: number | string
): true | string {
    if (!value || !value.trim()) {
        return 'Please enter password.'
    }
    if (typeof constraint === 'number' && value.length < constraint) {
        return `Password is too short, min ${constraint} characters.`
    }
    if (typeof constraint === 'string' && value !== constraint) {
        return `Passwords do not match.`
    }
    return true
}

export function getErrorForMachineName(
    value: string,
    checkExisting?: boolean
): true | string {
    value = value.trim()
    const exist: boolean = StorageHelper.get().findMachine(value) ? true : false
    if (exist && !checkExisting) {
        return `${StdOutUtil.getColoredMachineName(
            value
        )} already exist. If you want to replace the existing entry, you have to first use <logout> command, and then re-login.`
    }
    if (checkExisting && !exist) {
        return `${StdOutUtil.getColoredMachineName(
            value
        )} CapRover machine does not exist.`
    }
    if (checkExisting || isNameValid(value)) {
        return true
    }
    return 'Please enter a valid CapRover machine name: small letters, numbers, single hyphen.'
}

export function getErrorForAppName(
    apps: IAppDef[],
    value: string
): true | string {
    value = value.trim()
    const app = apps.find((a) => a.appName === value)
    if (!app) {
        return `${StdOutUtil.getColoredAppName(
            value
        )} app does not exist on this CapRover machine.`
    }
    if (app.isAppBuilding) {
        return `${StdOutUtil.getColoredAppName(
            value
        )} app is currently in a building process.`
    }
    return true
}

export function getErrorForBranchName(value: string): true | string {
    if (!value || !value.trim()) {
        return 'Please enter branch name.'
    }
    value = value.trim()
    try {
        const cmd = isWindows
            ? execSync(`git rev-parse ${value} > NUL`)
            : execSync(`git rev-parse ${value} 2>/dev/null`)
        if (cmd) {
            return true
        }
    } catch (e) {
        // Do nothing
    }
    return `Cannot find hash of last commit on branch "${value}".`
}

export function getErrorForEmail(value: string): true | string {
    if (!value || !value.trim()) {
        return 'Please enter email.'
    }
    if (!Utils.isValidEmail(value)) {
        return 'Please enter a valid email.'
    }
    return true
}

export function userCancelOperation(cancel: boolean, c?: boolean): boolean {
    if (cancel) {
        StdOutUtil.printMessage(
            (c ? '\n' : '') +
                '\nOperation cancelled by the user!' +
                (!c ? '\n' : ''),
            true
        )
    }
    return false
}
